/**
 * LRU cache backed by Map insertion order.
 * On get/set the entry is moved to the MRU end; the LRU entry (first key) is
 * evicted when the map is full. `maxSize = 0` means unlimited.
 */
class LruCache {
  /** @param {number} [maxSize=0] Maximum number of entries; 0 = unlimited. */
  constructor(maxSize = 0) {
    this._map = new Map()
    this._maxSize = maxSize
  }

  /** @param {*} key Cache key. */
  get(key) {
    const value = this._map.get(key)
    if (value !== undefined) {
      this._map.delete(key)
      this._map.set(key, value)
    }
    return value
  }

  /**
   * @param {*} key Cache key. `null` and `undefined` are ignored.
   * @param {*} value Value to store.
   * @param {number} [ttl] Time-to-live in milliseconds. Entry is auto-deleted after this duration.
   */
  set(key, value, ttl) {
    if (key == null) return
    this._map.delete(key)
    if (this._maxSize > 0 && this._map.size >= this._maxSize) this._map.delete(this._map.keys().next().value)
    this._map.set(key, value)
    if (ttl > 0) setTimeout(() => this._map.delete(key), ttl).unref()
  }

  /** @param {*} key Cache key. */
  delete(key) {
    this._map.delete(key)
  }
}

module.exports = { LruCache }
